import SwiftUI
struct CheckList: View {
    @State private var items = ["A", "B"]
    var body: some View {
        List(items, id: \.self) { item in Text(item) }
            .onDelete { indexSet in items.remove(atOffsets: indexSet) }
    }
}

import SwiftUI
struct CheckList: View {
    @State private var items = ["A", "B"]
    var body: some View {
        List {
            ForEach(items, id: \.self) { item in Text(item) }
                .onDelete { indexSet in items.remove(atOffsets: indexSet) }
        }
    }
}
